134			doc := fixStore{Format: 1, Devices: map[string]fixState{
135				"dev-1": {
136					Version:  "1.0",
137					Online:   true,
138					Revision: 1,
139					// 字段顺序不同、1 与 1.0 等值：无差异，无计时记录。
140					Desired:        json.RawMessage(`{"a":1,"b":{}}`),
141					Reported:       json.RawMessage(`{"b":{},"a":1.0}`),
142					LastSeq:        1,
143					LastReportTime: at,
