154			}
155			defer s.Close()
156			if diffs, _ := s.Diff("dev-1"); len(diffs) != 0 {
157				t.Fatalf("unexpected diffs: %+v", diffs)
158			}
159		})
160	
161		t.Run("new empty device and explicit empty record", func(t *testing.T) {
162			// 走正常流程登记：双方均为空对象，无差异。
163			s, dir := openTemp(t)
164			mustRegister(t, s, "dev-1", "1.0")
165			if err := s.Close(); err != nil {
166				t.Fatal(err)
167			}
168			s2, err := Open(dir)
169			if err != nil {
170				t.Fatalf("new empty-object device must reopen: %v", err)
171			}
172			s2.Close()
173	
174			// 手写一份显式保存空计时记录的无差异存储，同样必须能打开。
175			dir2 := t.TempDir()
176			raw := `{"format":1,"devices":{"dev-1":{"version":"1.0","revision":0,` +
177				`"desired":{},"reported":{},"diffSince":{}}}}`
178			if err := os.WriteFile(filepath.Join(dir2, storeFileName), []byte(raw), 0o644); err != nil {
179				t.Fatal(err)
180			}
181			s3, err := Open(dir2)
182			if err != nil {
183				t.Fatalf("empty diffSince record must open: %v", err)
184			}
185			defer s3.Close()
186			if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
187				t.Fatalf("unexpected diffs: %+v", diffs)
188			}
189		})
190	}
