192	// 实际差异缺时间、残留无差异路径、时间为零、父路径代替子路径、
193	// 条数相同但路径不同：都必须返回 ErrCorruptStorage 拒绝打开整个存储，
194	// 且原文件内容保持不变，不补当前时间、不删多余记录、不重写配置。
195	func TestRestoreDiffSinceCorruptRefused(t *testing.T) {
196		cases := map[string]func(fixStore){
197			// 实际存在 /wifi/ssid 差异，却完全没有计时记录。
198			"missing time record": func(doc fixStore) {
199				d := doc.Devices["dev-1"]
200				d.DiffSince = nil
201				doc.Devices["dev-1"] = d
202			},
203			// 已相等的 /mode 仍残留时间记录。
204			"stale record for equal path": func(doc fixStore) {
205				d := doc.Devices["dev-1"]
206				d.DiffSince["/mode"] = "2026-10-02T12:00:00Z"
207				doc.Devices["dev-1"] = d
208			},
209			// 只残留无关路径，实际差异反而没有记录。
210			"only stale record": func(doc fixStore) {
211				d := doc.Devices["dev-1"]
212				d.DiffSince = map[string]string{"/mode": "2026-10-02T12:00:00Z"}
213				doc.Devices["dev-1"] = d
214			},
215			// 路径正确但时间为零值。
216			"zero first-seen time": func(doc fixStore) {
217				d := doc.Devices["dev-1"]
218				d.DiffSince = map[string]string{"/wifi/ssid": "0001-01-01T00:00:00Z"}
219				doc.Devices["dev-1"] = d
220			},
221			// 父路径 /wifi 的时间不能替代子路径 /wifi/ssid（条数相同）。
222			"parent path cannot cover child": func(doc fixStore) {
223				d := doc.Devices["dev-1"]
224				d.DiffSince = map[string]string{"/wifi": "2026-10-02T12:00:00Z"}
225				doc.Devices["dev-1"] = d
226			},
227			// 记录条数与差异条数相同，但路径对不上。
228			"same count different path": func(doc fixStore) {
229				d := doc.Devices["dev-1"]
230				d.DiffSince = map[string]string{"/wifi/chan": "2026-10-02T12:00:00Z"}
231				doc.Devices["dev-1"] = d
232			},
233		}
234		for name, mutate := range cases {
235			t.Run(name, func(t *testing.T) {
236				doc := diffSinceDoc()
237				mutate(doc)
238				dir, original := writeFixStore(t, doc)
239				s, err := Open(dir)
240				if err == nil {
241					s.Close()
242					t.Fatalf("expected ErrCorruptStorage")
243				}
244				if !errors.Is(err, ErrCorruptStorage) {
245					t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
246				}
247				data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
248				if rerr != nil {
249					t.Fatal(rerr)
250				}
251				if string(data) != string(original) {
252					t.Fatalf("corrupt file modified on rejected open")
253				}
254			})
255		}
