267					LastReportTime: "2026-10-02T12:00:00Z",
268					DiffSince:      map[string]string{"/a": "2026-10-02T12:00:00Z"},
269					Audit: []fixAudit{
270						{Operator: "op", Time: "2026-10-02T12:00:00Z", Revision: 1,
271							Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":1}`)},
272					},
273				},
274			}}
275			dir, original := writeFixStore(t, doc)
276			if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
277				t.Fatalf("stale time on equal device must be refused: %v", err)
278			}
279			if data, _ := os.ReadFile(filepath.Join(dir, storeFileName)); string(data) != string(original) {
280				t.Fatalf("corrupt file modified on rejected open")
281			}
282		})
283	}
284	
285	// 一台设备的计时记录损坏即拒绝打开整个存储，其他设备再正常也不可只跳过坏设备。
286	func TestRestoreDiffSinceOneBadDeviceRejectsAll(t *testing.T) {
287		doc := diffSinceDoc() // dev-1 合法
288		doc.Devices["good"] = fixState{
289			Version:  "1.0",
290			Desired:  json.RawMessage(`{}`),
291			Reported: json.RawMessage(`{}`),
292		}
293		bad := diffSinceDoc().Devices["dev-1"]
294		bad.DiffSince = nil // dev-2 有 /wifi/ssid 差异但缺时间记录
295		doc.Devices["bad"] = bad
296		dir, _ := writeFixStore(t, doc)
297		if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
298			t.Fatalf("whole store must be refused when one device lacks diff times: %v", err)
299		}
300	}
301	
302	// 跨关闭重开的计时生命周期：同一路径持续不同保留原时间；差异消失后再次出现
303	// 才重新计时，且恢复出的计时记录与正常流程产生的记录行为一致。
304	func TestRestoreDiffSinceLifecycleAcrossReopen(t *testing.T) {
305		t1 := base
306		s, dir := openTemp(t)
307		mustRegister(t, s, "dev-1", "1.0")
308		if _, err := s.UpdateDesired("dev-1", "op", t1, 0, json.RawMessage(`{"a":1}`)); err != nil {
309			t.Fatal(err)
310		}
311		if err := s.Close(); err != nil {
312			t.Fatal(err)
313		}
314	
315		// 重开后同一路径仍不同：保留首次时间。
316		s2, err := Open(dir)
317		if err != nil {
318			t.Fatalf("reopen with diff: %v", err)
319		}
320		if diffs, _ := s2.Diff("dev-1"); len(diffs) != 1 || !diffs[0].Since.Equal(t1) {
321			t.Fatalf("diff time must survive reopen: %+v", diffs)
322		}
323		// 重开后继续改值但仍不相等：沿用原时间。
324		t2 := base.Add(time.Minute)
325		if _, err := s2.UpdateDesired("dev-1", "op", t2, 1, json.RawMessage(`{"a":2}`)); err != nil {
326			t.Fatal(err)
327		}
328		if diffs, _ := s2.Diff("dev-1"); !diffs[0].Since.Equal(t1) {
329			t.Fatalf("persistent diff must keep original time: %+v", diffs)
330		}
331		// 差异消失，关闭重开：无差异、无计时记录仍合法。
332		t3 := base.Add(2 * time.Minute)
333		if err := s2.Report("dev-1", 1, t3, "1.0", json.RawMessage(`{"a":2}`)); err != nil {
334			t.Fatal(err)
335		}
336		if err := s2.Close(); err != nil {
337			t.Fatal(err)
338		}
339		s3, err := Open(dir)
340		if err != nil {
341			t.Fatalf("reopen without diffs: %v", err)
342		}
343		if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
344			t.Fatalf("cleared diff must stay cleared: %+v", diffs)
345		}
346		// 同一路径再次出现差异：必须重新计时，不能沿用消失前的 t1。
347		t4 := base.Add(3 * time.Minute)
348		if _, err := s3.UpdateDesired("dev-1", "op", t4, 2, json.RawMessage(`{"a":3}`)); err != nil {
349			t.Fatal(err)
350		}
351		if err := s3.Close(); err != nil {
352			t.Fatal(err)
353		}
354		s4, err := Open(dir)
355		if err != nil {
356			t.Fatalf("final reopen: %v", err)
357		}
358		defer s4.Close()
359		diffs, _ := s4.Diff("dev-1")
360		if len(diffs) != 1 || diffs[0].Path != "/a" || !diffs[0].Since.Equal(t4) {
361			t.Fatalf("reappeared diff must restart timing at t4: %+v", diffs)
362		}
363	}
