306		// 差异时间：/wifi/ssid 等在上报时首次出现
307		for _, d := range diffs {
308			want := t2
309			if d.Path == "/onlyDesired" || d.Path == "/nullField" || d.Path == "/arr" {
310				// 上报前 desired 已有而 reported 为空对象，差异在修改期望时已出现
311				want = t1
312			}
313			if !d.Since.Equal(want) {
314				t.Fatalf("%s since: want %v got %v", d.Path, want, d.Since)
315			}
316		}
